+GroupedGemmSubmission grouped_gemm_diagnostic(sycl::queue& q, const uint16_t* X, const uint16_t* W,
+                                             int64_t w_stride, float* Y, const int32_t* bounds, int G,
+                                             int64_t max_rows, int64_t N, int64_t K) {
+    auto& runtime = core::Runtime::get();
+    if (q.get_device() != runtime.device() || q.get_context() != runtime.context() ||
+        !q.has_property<sycl::property::queue::in_order>() ||
+        !q.has_property<sycl::property::queue::enable_profiling>() ||
+        !q.get_device().has(sycl::aspect::queue_profiling))
+        throw core::DeviceError("grouped diagnostic: queue identity/profiling mismatch");
+    // Narrow bounded synthetic API. Bounds must be immutable validated host/shared USM from this context.
+    if (G != 16 || max_rows < 1 || max_rows > 256 ||
+        !((N == 1280 && K == 2560) || (N == 2560 && K == 640)) || w_stride != N * K)
+        throw core::DeviceError("grouped diagnostic: unsupported geometry");
+    if (!X || !W || !Y || !bounds) throw core::DeviceError("grouped diagnostic: null pointer");
+    for (const void* pointer : {static_cast<const void*>(X), static_cast<const void*>(W), static_cast<const void*>(Y)}) {
+        const auto allocation = sycl::get_pointer_type(pointer, q.get_context());
+        if (allocation != sycl::usm::alloc::shared && allocation != sycl::usm::alloc::device)
+            throw core::DeviceError("grouped diagnostic: operand context/allocation mismatch");
+        if (sycl::get_pointer_device(pointer, q.get_context()) != q.get_device())
+            throw core::DeviceError("grouped diagnostic: operand device mismatch");
+    }
+    const auto kind = sycl::get_pointer_type(bounds, q.get_context());
+    if (kind != sycl::usm::alloc::shared && kind != sycl::usm::alloc::host)
+        throw core::DeviceError("grouped diagnostic: bounds must be host accessible USM");
+    if (bounds[0] != 0) throw core::DeviceError("grouped diagnostic: bounds origin");
+    for (int g = 0; g < G; ++g)
+        if (bounds[g] < 0 || bounds[g + 1] < bounds[g] || bounds[g + 1] - bounds[g] > max_rows)
+            throw core::DeviceError("grouped diagnostic: invalid bounds");
+    return submit_grouped(q, X, W, w_stride, Y, bounds, G, max_rows, N, K, true);
 }
